from typing import List
from dataclasses import dataclass
import enum

class ResultType(enum.Enum):
    SUCCESS = "success"
    FAILURE = "failure"

@dataclass
class StepResponse:
    result: ResultType

@dataclass
class CreditChargesPayment:
    txn_id: str
    open_balance: float
    linked_payment_amount: str = ""

class PaymentChargesTableAction:
    @staticmethod
    def full_credits_table_update(credits_table: List[CreditChargesPayment]) -> None:
        pass

class PaymentTableSelectors:
    @staticmethod
    def get_credits() -> List[CreditChargesPayment]:
        return []

    @staticmethod
    def get_total_of_charges_table() -> float:
        return 0.0

def outstanding_transactions_handler_simplified() -> StepResponse:
    """
    Simplified version that eliminates deep copies while maintaining functionality.
    """
    try:
        credit_table_lines = PaymentTableSelectors.get_credits()
        total_charges = PaymentTableSelectors.get_total_of_charges_table()

        if not credit_table_lines or total_charges <= 0:
            PaymentChargesTableAction.full_credits_table_update([])
            return StepResponse(result=ResultType.SUCCESS)

        remaining_balance = float(total_charges)
        updated_credits = []
        has_updates = False

        for credit in credit_table_lines:
            if not credit.linked_payment_amount.strip():
                updated_credits.append(credit)
                continue

            if remaining_balance >= credit.open_balance:
                new_amount = str(credit.open_balance)
                remaining_balance -= credit.open_balance
            elif remaining_balance > 0:
                new_amount = str(remaining_balance)
                remaining_balance = 0
            else:
                new_amount = ""

            if credit.linked_payment_amount != new_amount:
                has_updates = True
                updated_credit = CreditChargesPayment(
                    txn_id=credit.txn_id,
                    open_balance=credit.open_balance,
                    linked_payment_amount=new_amount
                )
                updated_credits.append(updated_credit)
            else:
                updated_credits.append(credit)

        if has_updates:
            PaymentChargesTableAction.full_credits_table_update(updated_credits)

        return StepResponse(result=ResultType.SUCCESS)

    except Exception as e:
        return StepResponse(result=ResultType.FAILURE)

# Explicitly handle the case when totalOfChargesTable is 0
def outstanding_transactions_handler_edge_case() -> StepResponse:
    """
    Specialized version that explicitly handles zero total charges.
    """
    try:
        credit_table_lines = PaymentTableSelectors.get_credits()
        total_charges = PaymentTableSelectors.get_total_of_charges_table()

        if not credit_table_lines:
            PaymentChargesTableAction.full_credits_table_update([])
            return StepResponse(result=ResultType.SUCCESS)

        # Explicit zero charge handling
        if total_charges == 0:
            updated_credits = []
            for credit in credit_table_lines:
                if credit.linked_payment_amount.strip():
                    updated_credit = CreditChargesPayment(
                        txn_id=credit.txn_id,
                        open_balance=credit.open_balance,
                        linked_payment_amount=""
                    )
                    updated_credits.append(updated_credit)
                else:
                    updated_credits.append(credit)

            if updated_credits != credit_table_lines:
                PaymentChargesTableAction.full_credits_table_update(updated_credits)
            return StepResponse(result=ResultType.SUCCESS)

        # Normal processing for non-zero charges
        remaining_balance = float(total_charges)
        updated_credits = []
        has_updates = False

        for credit in credit_table_lines:
            if not credit.linked_payment_amount.strip():
                updated_credits.append(credit)
                continue

            if remaining_balance >= credit.open_balance:
                new_amount = str(credit.open_balance)
                remaining_balance -= credit.open_balance
            elif remaining_balance > 0:
                new_amount = str(remaining_balance)
                remaining_balance = 0
            else:
                new_amount = ""

            if credit.linked_payment_amount != new_amount:
                has_updates = True
                updated_credit = CreditChargesPayment(
                    txn_id=credit.txn_id,
                    open_balance=credit.open_balance,
                    linked_payment_amount=new_amount
                )
                updated_credits.append(updated_credit)
            else:
                updated_credits.append(credit)

        if has_updates:
            PaymentChargesTableAction.full_credits_table_update(updated_credits)

        return StepResponse(result=ResultType.SUCCESS)

    except Exception as e:
        return StepResponse(result=ResultType.FAILURE)

