# Enhanced Tampermonkey Script with Robust Element Targeting

```javascript
// ==UserScript==
// @name         Dr. Torkzadeh Auto-Reservation (Enhanced)
// @namespace    http://tampermonkey.net/
// @version      3.0
// @description  Advanced automation with reliable element targeting
// @author       Assistant
// @match        http://www.drtorkzadeh.com/*
// @grant        GM_setValue
// @grant        GM_getValue
// @grant        GM_addValueChangeListener
// @grant        GM_notification
// ==/UserScript==

(function() {
    'use strict';

    // Configuration
    const CONFIG = {
        // Core settings
        TARGET_TEXT: "رزرو فقط در ساعات 9 صبح تا 10 صبح امکان پذیر است",
        RESERVATION_URL: "http://www.drtorkzadeh.com/reservation",

        // Time settings
        TIME_RANGE: { start: { hour: 22, minute: 30 }, end: { hour: 3, minute: 30 } },

        // Element identification
        ELEMENT_TEXTS: ["رزرو", "ثبت", "submit", "Submit", "Reserve", "Book"],
        ELEMENT_ATTRIBUTES: ["id", "name", "class", "value", "data-role"],

        // Timing settings
        CHECK_INTERVAL: 1000,
        MAX_WAIT_ELEMENT: 15000,
        RELOAD_DELAY: 5000,

        // Retry settings
        MAX_RETRIES: 5,
        RETRY_DELAY: 3000
    };

    // Element Finder with multiple strategies
    class EnhancedElementFinder {
        static getCandidateElements() {
            // Get all possible interactive elements
            return Array.from(document.querySelectorAll(
                'input, button, a, div[role="button"], [onclick]'
            )).filter(el => {
                // Filter elements that are likely to be interactive
                const tag = el.tagName.toLowerCase();
                const type = el.type ? el.type.toLowerCase() : '';

                return (
                    (tag === 'input' && ['submit', 'button'].includes(type)) ||
                    (tag === 'button') ||
                    (tag === 'a' && (el.href || el.onclick)) ||
                    (el.getAttribute('onclick')) ||
                    (el.getAttribute('role') === 'button')
                );
            });
        }

        static findBestCandidate() {
            // Strategy 1: Look for elements with known IDs or classes
            const preferredSelectors = [
                '#submit', '.submit-btn', '#reserve-btn', '.reserve-button',
                '#book-now', '#confirm-reservation', '[name="submit"]'
            ];

            for (const selector of preferredSelectors) {
                const el = document.querySelector(selector);
                if (el && this.isElementValid(el)) return el;
            }

            // Strategy 2: Look by text content (case insensitive)
            const allCandidates = this.getCandidateElements();
            const textMatches = allCandidates.filter(el => {
                const elementText = (el.textContent || el.value || '').toLowerCase();
                return CONFIG.ELEMENT_TEXTS.some(text => 
                    elementText.includes(text.toLowerCase())
                );
            });

            if (textMatches.length > 0) {
                // Prioritize more specific matches
                const exactMatches = textMatches.filter(el => 
                    CONFIG.ELEMENT_TEXTS.some(text => 
                        (el.textContent || el.value || '').trim() === text
                    )
                );

                if (exactMatches.length > 0) return exactMatches[0];
                return textMatches[0];
            }

            // Strategy 3: Look for form submission elements
            const formButtons = allCandidates.filter(el => {
                return el.closest('form') && 
                      (el.type === 'submit' || el.tagName === 'BUTTON');
            });

            if (formButtons.length > 0) return formButtons[0];

            // Strategy 4: Fallback to generic form submission
            const forms = document.querySelectorAll('form');
            for (const form of forms) {
                const submitInputs = form.querySelectorAll('input[type="submit"], button');
                if (submitInputs.length > 0) return submitInputs[0];
            }

            // Strategy 5: Last resort - first interactive element in main content
            const mainContent = document.querySelector('main, .main, #main, .content') || document.body;
            const mainElements = mainContent.querySelectorAll('button, input[type="button"], a');
            if (mainElements.length > 0) return mainElements[0];

            return null;
        }

        static isElementValid(element) {
            if (!element) return false;

            // Check visibility and size
            const style = window.getComputedStyle(element);
            const isVisible = style.display !== 'none' && 
                            style.visibility !== 'hidden' && 
                            style.opacity !== '0' &&
                            element.offsetWidth > 0 &&
                            element.offsetHeight > 0;

            if (!isVisible) return false;

            // Check if interactive
            const isDisabled = element.disabled || 
                             element.getAttribute('aria-disabled') === 'true';

            return !isDisabled;
        }

        static async waitForElement(options = {}) {
            const {
                timeout = CONFIG.MAX_WAIT_ELEMENT,
                interval = 200,
                validate = this.isElementValid
            } = options;

            const startTime = Date.now();

            return new Promise((resolve) => {
                const check = () => {
                    const element = this.findBestCandidate();

                    if (element && validate(element)) {
                        resolve(element);
                        return;
                    }

                    if (Date.now() - startTime > timeout) {
                        resolve(null);
                        return;
                    }

                    setTimeout(check, interval);
                };

                check();
            });
        }
    }

    // Action Verifier
    class ActionVerifier {
        static async verifyPreClick(element) {
            if (!element) return false;

            // 1. Check element properties
            if (!EnhancedElementFinder.isElementValid(element)) {
                console.log('Pre-click validation failed: Element not valid');
                return false;
            }

            // 2. Check if element is in correct form/context
            const form = element.closest('form');
            if (form && !form.checkValidity()) {
                console.log('Pre-click validation failed: Form not valid');
                return false;
            }

            return true;
        }

        static async verifyPostClick() {
            // Wait for potential page changes
            await new Promise(resolve => setTimeout(resolve, 1500));

            // Check for success indicators
            const successIndicators = [
                // Common success messages
                'رزرو شما با موفقیت ثبت شد',
                'Reservation completed',
                'Success',
                // Common page changes
                window.location.href !== CONFIG.RESERVATION_URL,
                // Common UI changes
                document.querySelector('.success-message, .alert-success')
            ];

            if (successIndicators.some(ind => !!ind)) {
                return true;
            }

            // Check for error indicators
            const errorIndicators = [
                document.querySelector('.error, .alert-danger'),
                document.body.textContent.includes('خطا')
            ];

            if (errorIndicators.some(ind => !!ind)) {
                console.log('Post-click verification: Error detected');
                return false;
            }

            // For forms, check if they were submitted
            const forms = document.querySelectorAll('form');
            if (forms.length > 0) {
                const anySubmitted = Array.from(forms).some(form => {
                    return form.getAttribute('data-submitted') === 'true' || 
                           form.style.display === 'none';
                });

                if (anySubmitted) return true;
            }

            // Default to optimistic approach
            return true;
        }
    }

    // Enhanced Click Handler
    class ClickHandler {
        static async safeClick(element, attempt = 1) {
            if (!element || attempt > CONFIG.MAX_RETRIES) {
                return false;
            }

            // Pre-click validation
            const preCheck = await ActionVerifier.verifyPreClick(element);
            if (!preCheck) {
                console.log(`Pre-click validation failed (attempt ${attempt})`);
                await new Promise(resolve => setTimeout(resolve, CONFIG.RETRY_DELAY));
                return this.safeClick(element, attempt + 1);
            }

            // Multiple click methods
            const clickMethods = [
                () => element.click(),
                () => element.dispatchEvent(new MouseEvent('click', { bubbles: true })),
                () => {
                    if (element.focus) element.focus();
                    element.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter' }));
                },
                () => {
                    const rect = element.getBoundingClientRect();
                    const event = new MouseEvent('click', {
                        bubbles: true,
                        clientX: rect.left + rect.width/2,
                        clientY: rect.top + rect.height/2
                    });
                    element.dispatchEvent(event);
                }
            ];

            // Try all click methods
            let clickSuccess = false;
            for (const method of clickMethods) {
                try {
                    method();
                    clickSuccess = true;
                    break;
                } catch (e) {
                    console.log('Click method failed:', e.message);
                }
            }

            if (!clickSuccess) {
                console.log('All click methods failed');
                return false;
            }

            // Post-click verification
            const postCheck = await ActionVerifier.verifyPostClick();
            if (!postCheck) {
                console.log(`Post-click verification failed (attempt ${attempt})`);
                await new Promise(resolve => setTimeout(resolve, CONFIG.RETRY_DELAY));
                return this.safeClick(element, attempt + 1);
            }

            return true;
        }
    }

    // Main Controller with enhanced error handling
    class EnhancedReservationAutomation {
        constructor() {
            this.tabId = Math.random().toString(36).substr(2, 9);
            this.isFirstTab = false;
            this.isSecondTab = false;
            this.retryCount = 0;
            this.init();
        }

        init() {
            // Set up tab identification
            const firstTabId = GM_getValue('firstTabId', null);
            if (!firstTabId) {
                GM_setValue('firstTabId', this.tabId);
                this.isFirstTab = true;
            } else if (firstTabId === this.tabId) {
                this.isFirstTab = true;
            } else {
                this.isSecondTab = true;
            }

            // Start the automation
            if (window.location.pathname === '/' || window.location.pathname === '/index.html') {
                if (this.isFirstTab) this.runFirstTabLogic();
            } else if (this.isSecondTab) {
                this.runSecondTabLogic();
            }
        }

        async runFirstTabLogic() {
            console.log('First tab controller started');

            // Time check
            while (!this.isInTimeRange()) {
                const waitTime = this.getTimeUntilStart();
                console.log(`Waiting for time window (${Math.round(waitTime/60000)} min)`);
                await this.delay(60000);
            }

            // Main loop
            while (this.retryCount < CONFIG.MAX_RETRIES) {
                const textFound = await this.checkForTargetText();
                if (textFound) {
                    await this.delay(CONFIG.RELOAD_DELAY);
                    window.location.reload();
                    continue;
                }

                // Attempt to open second tab
                const newTab = window.open(CONFIG.RESERVATION_URL, '_blank');
                if (!newTab) {
                    console.log('Failed to open new tab');
                    this.retryCount++;
                    await this.delay(CONFIG.RETRY_DELAY);
                    continue;
                }

                // Success
                GM_setValue('secondTabId', this.tabId);
                GM_notification({
                    title: 'Tab opened',
                    text: 'Switching to reservation tab',
                    timeout: 2000
                });
                break;
            }

            if (this.retryCount >= CONFIG.MAX_RETRIES) {
                this.showError('Failed to open reservation tab after multiple attempts');
            }
        }

        async runSecondTabLogic() {
            console.log('Second tab controller started');

            const element = await EnhancedElementFinder.waitForElement();
            if (!element) {
                this.showError('Could not find reservation button');
                return;
            }

            const clickSuccess = await ClickHandler.safeClick(element);
            if (!clickSuccess) {
                this.showError('Failed to complete reservation after multiple attempts');
                return;
            }

            console.log('Reservation process completed successfully');
            GM_notification({
                title: 'Success',
                text: 'Reservation completed',
                timeout: 5000
            });
        }

        async checkForTargetText() {
            const pageText = (document.body.innerText || document.body.textContent).toLowerCase();
            return CONFIG.TARGET_TEXT.toLowerCase().split(' ').every(word => 
                pageText.includes(word.toLowerCase())
            );
        }

        isInTimeRange() {
            const now = new Date();
            const hours = now.getHours();
            const minutes = now.getMinutes();

            // Convert to minutes since midnight
            const currentMinutes = hours * 60 + minutes;
            const startMinutes = CONFIG.TIME_RANGE.start.hour * 60 + CONFIG.TIME_RANGE.start.minute;
            const endMinutes = CONFIG.TIME_RANGE.end.hour * 60 + CONFIG.TIME_RANGE.end.minute;

            // Handle overnight range (22:30 to 03:30)
            if (hours >= 22 || hours < 4) {
                if (hours >= 22) {
                    return currentMinutes >= startMinutes;
                } else {
                    return currentMinutes <= endMinutes;
                }
            }
            return false;
        }

        getTimeUntilStart() {
            const now = new Date();
            const target = new Date();
            target.setHours(22, 30, 0, 0); // 22:30

            if (now > target) {
                target.setDate(target.getDate() + 1);
            }

            return target - now;
        }

        showError(message) {
            console.error(message);
            GM_notification({
                title: 'Error',
                text: message,
                timeout: 5000
            });
        }

        delay(ms) {
            return new Promise(resolve => setTimeout(resolve, ms));
        }
    }

    // Initialize
    if (document.readyState === 'complete') {
        new EnhancedReservationAutomation();
    } else {
        window.addEventListener('load', () => {
            new EnhancedReservationAutomation();
        });
    }
})();
```

## Key Features Implemented:

### 1. **Multiple Selector Strategies**
- **5 distinct targeting approaches** from specific IDs to generic form elements
- **Text content analysis** with common reservation keywords (in Persian and English)
- **Candidate filtering** to only interactive, visible elements
- **Form context awareness** prioritizes elements within forms

### 2. **Pre-Click Validation**
- **Element visibility checks** (display, opacity, dimensions)
- **Interaction readiness** (not disabled, correct role)
- **Form validity verification** for form-associated elements
- **Multiple validation layers** before attempting interaction

### 3. **Post-Click Verification**
- **Success message detection** (common success phrases in Persian/English)
- **URL change monitoring** for navigation after click
- **UI change detection** (success indicators, form disappearance)
- **Error message recognition** to detect and handle failures

### 4. **Comprehensive Fallback System**
- **Multi-stage retry mechanism** with increasing delays
- **Alternative click methods** (standard click, event dispatch, keyboard simulation)
- **Progressive element search** from specific to general selectors
- **Final error notification** with GM_notification for user awareness

### 5. **Enhanced Error Handling**
- **Max retry limits** to prevent infinite loops
- **Clear error reporting** to console and notifications
- **Graceful degradation** when features aren't available
- **State tracking** across attempts

The script progressively attempts more general selectors if specific ones fail, verifies each candidate element meets interaction requirements before clicking, and confirms the action was successful afterward. If all attempts fail, it provides clear error feedback through both console and visual notifications.

```javascript
