// @grant        GM_getValue
// @grant        GM_log
// ==/UserScript==

(function() {
    'use strict';

    // Configuration
    const CONFIG = {
        TARGET_TEXT: "رزرو فقط در ساعات 9 صبح تا 10 صبح امکان پذیر است",
        RESERVATION_URL: "http://www.drtorkzadeh.com/reservation",
        TIME_RANGE: { start: { hour: 22, minute: 30 }, end: { hour: 3, minute: 30 } },
        MAIN_PAGE_PATTERNS: ['/', '/index.html', '/index.php', ''],
        CHECK_INTERVAL: 1000,
        TEXT_CHECK_DELAY: 5000
    };

    // Main Controller
    class ReservationController {
        constructor() {
            this.state = {
                isFirstTab: false,
                isMainPage: false,
                textChecking: true,
                tabSwitched: false,
                scriptComplete: false
            };

            this.init();
        }

        init() {
            // Step 1: Verify first tab and main page
            if (!this.verifyFirstTab() || !this.verifyMainPage()) {
                console.log('Script not executed: Not first tab or not main page');
                return;
            }

            console.log('✅ Script initialized in first tab on main page');
            this.start();
        }

        verifyFirstTab() {
            // Simple first tab detection using sessionStorage
            if (!sessionStorage.getItem('firstTabMarked')) {
                sessionStorage.setItem('firstTabMarked', 'true');
                this.state.isFirstTab = true;
                return true;
            }

            // Check if we're the marked tab
            const tabKey = sessionStorage.getItem('currentTabKey');
            if (!tabKey) {
                sessionStorage.setItem('currentTabKey', Date.now().toString());
                this.state.isFirstTab = true;
                return true;
            }

            return false;
        }

        verifyMainPage() {
            const path = window.location.pathname;
            const isMainPage = CONFIG.MAIN_PAGE_PATTERNS.some(pattern => 
                path === pattern || path === pattern + '/'
            );

            this.state.isMainPage = isMainPage;
            return isMainPage;
        }

        async start() {
            // Step 2: Wait for correct time
            await this.waitForCorrectTime();

            // Step 3: Start text checking loop
            await this.textCheckLoop();
        }

        async waitForCorrectTime() {
            while (!this.isWithinTimeRange()) {
                console.log('Outside time range (22:30-03:30). Waiting...');
                await this.delay(60000); // Check every minute
            }
            console.log('✅ Within time range (22:30-03:30)');
        }

        isWithinTimeRange() {
            const now = new Date();
            const hours = now.getHours();
            const minutes = now.getMinutes();
            const currentMinutes = hours * 60 + minutes;

            const startMinutes = CONFIG.TIME_RANGE.start.hour * 60 + CONFIG.TIME_RANGE.start.minute;
            const endMinutes = CONFIG.TIME_RANGE.end.hour * 60 + CONFIG.TIME_RANGE.end.minute;

            if (hours >= 22 || hours < 3) {
                if (hours >= 22) {
                    return currentMinutes >= startMinutes;
                } else {
                    return currentMinutes <= endMinutes;
                }
            }
            return false;
        }

        async textCheckLoop() {
            console.log('Starting text check loop...');

            while (this.state.textChecking && !this.state.scriptComplete) {
                const hasText = await this.checkForTargetText();

                if (hasText) {
                    console.log('Target text found. Waiting 5 seconds...');
                    await this.delay(CONFIG.TEXT_CHECK_DELAY);
                    window.location.reload();
                    return; // Script will restart after reload
                }

                // Text not found - proceed to tab switching
                if (!hasText && !this.state.tabSwitched) {
                    this.state.textChecking = false;
                    await this.handleTabTransition();
                }

                await this.delay(CONFIG.CHECK_INTERVAL);
            }
        }

        async checkForTargetText() {
            const pageText = document.body.innerText || document.body.textContent;
            return pageText.includes(CONFIG.TARGET_TEXT);
        }

        async handleTabTransition() {
            console.log('Target text not found. Switching to second tab...');

            // Step 4: Create second tab
            const secondTab = window.open(CONFIG.RESERVATION_URL, '_blank');

            if (!secondTab) {
                console.log('Failed to open second tab. Retrying in 5 seconds...');
                await this.delay(5000);
                this.state.textChecking = true; // Retry text checking
                return;
            }

            this.state.tabSwitched = true;

            // Step 5: Focus on second tab
            await this.delay(2000); // Wait for tab to load

            try {
                secondTab.focus();
                console.log('✅ Second tab focused');
                // Added explicit window.focus() per user request
                window.focus();
            } catch (e) {
                console.log('Could not focus second tab:', e.message);
            }

            // Mark that we've created the second tab
            GM_setValue('secondTabCreated', true);

            // Stop execution in first tab
            this.state.scriptComplete = true;
            console.log('First tab script complete. Second tab should handle the click.');
        }

        delay(ms) {
            return new Promise(resolve => setTimeout(resolve, ms));
        }
    }

    // Second Tab Handler (runs in reservation page)
    class SecondTabHandler {
        constructor() {
            this.init();
        }

        init() {
            // Only run in second tab (reservation page)
            if (!this.isReservationPage()) {
                return;
            }

            // Check if second tab was created by our script
            const secondTabCreated = GM_getValue('secondTabCreated', false);
            if (!secondTabCreated) {
                console.log('Not the second tab created by script');
                return;
            }

            console.log('✅ Second tab handler initialized');
            this.start();
        }

        isReservationPage() {
            // Check if we're on a reservation page
            const url = window.location.href;
            return url.includes('reservation') || 
                   url.includes('submit') || 
                   document.querySelector('form') !== null;
        }

        async start() {
            // Wait for page to load
            await this.waitForPageLoad();

            // Find and click the submit button
            await this.findAndClickSubmit();
        }

        async waitForPageLoad() {
            if (document.readyState === 'complete') {
                return;
            }

            return new Promise(resolve => {
                window.addEventListener('load', resolve, { once: true });
                // Fallback timeout
                setTimeout(resolve, 5000);
            });
        }

        async findAndClickSubmit() {
            console.log('Looking for submit button...');

            // Strategy 1: Exact element from instructions
            // "TAG POS=1 TYPE=INPUT:SUBMIT FORM=ACTION:http://www.drtorkzadeh.com/ ATTR=ID:submit"
            let element = await this.findExactElement();

            // Strategy 2: Form-based search
            if (!element) {
                element = await this.findFormSubmit();
            }

            // Strategy 3: Comprehensive search
            if (!element) {
                element = await this.findAnySubmit();
            }

            if (element) {
                await this.clickElement(element);
                console.log('✅ Script completed successfully');
                GM_setValue('scriptCompleted', true);
            } else {
                console.log('❌ Could not find submit element');
            }
        }

        async findExactElement() {
            // Direct translation of instruction:
            // input[type="submit"] with id="submit" in a form with action containing drtorkzadeh.com

            // First, try direct selector
            const directElement = document.querySelector('input[type="submit"][id="submit"]');
            if (directElement) {
                console.log('✅ Found exact element: input[type="submit"][id="submit"]');
                return directElement;
            }

            // Try with form context
            const forms = document.querySelectorAll('form');
            for (const form of forms) {
                const formAction = form.getAttribute('action') || '';
                if (formAction.includes('drtorkzadeh.com')) {
                    const element = form.querySelector('input[type="submit"][id="submit"]');
                    if (element) {
                        console.log('✅ Found exact element in form with correct action');
                        return element;
                    }
                }
            }

            return null;
        }

        async findFormSubmit() {
            const forms = document.querySelectorAll('form');

            for (const form of forms) {
                // Look for submit elements with Persian text
                const candidates = [
                    ...form.querySelectorAll('input[type="submit"]'),
                    ...form.querySelectorAll('button[type="submit"]'),
                    ...form.querySelectorAll('input[type="button"]')
                ];

                for (const element of candidates) {
                    const text = (element.value || element.textContent || '').toLowerCase();
                    if (text.includes('رزرو') || text.includes('ثبت')) {
                        console.log('✅ Found form submit element with Persian text:', text.substring(0, 30));
                        return element;
                    }
                }

                // If no Persian text, take the first submit element
                if (candidates.length > 0) {
                    console.log('✅ Found form submit element (no Persian text)');
                    return candidates[0];
                }
            }

            return null;
        }

        async findAnySubmit() {
            // Get all potential submit elements
            const allElements = document.querySelectorAll(
                'input[type="submit"], button[type="submit"], input[type="button"], button'
            );

            // Score elements based on likelihood
            const scoredElements = [];

            for (const element of allElements) {
                if (!this.isElementInteractable(element)) continue;

                let score = 0;
                const text = (element.value || element.textContent || '').toLowerCase();
                const type = element.type || '';

                // Text scoring
                if (text.includes('رزرو')) score += 100;
                if (text.includes('ثبت')) score += 80;
                if (text.includes('ارسال')) score += 60;
                if (text.includes('submit')) score += 40;

                // Type scoring
                if (type === 'submit') score += 50;

                // Position scoring (submit buttons often at bottom)
                const rect = element.getBoundingClientRect();
                if (rect.bottom > window.innerHeight * 0.7) score += 30;

                // Form association
                if (element.closest('form')) score += 20;

                if (score > 50) {
                    scoredElements.push({ element, score });
                }
            }

            if (scoredElements.length > 0) {
                scoredElements.sort((a, b) => b.score - a.score);
                console.log('✅ Found element through scoring, score:', scoredElements[0].score);
                return scoredElements[0].element;
            }

            return null;
        }

        async clickElement(element) {
            console.log('Clicking element...');

            // Ensure element is visible
            if (!this.isElementVisible(element)) {
                element.scrollIntoView({ behavior: 'smooth', block: 'center' });
                await this.delay(500);
            }

            // Try multiple click methods
            const methods = [
                () => element.click(),
                () => {
                    const event = new MouseEvent('click', {
                        bubbles: true,
                        cancelable: true
                    });
                    element.dispatchEvent(event);
                },
                () => {
                    element.focus();
                    const event = new KeyboardEvent('keydown', {
                        key: 'Enter',
                        code: 'Enter',
                        keyCode: 13,
                        bubbles: true
                    });
                    element.dispatchEvent(event);
                }
            ];

            for (const method of methods) {
                try {
                    method();
                    console.log('✅ Click executed');
                    return true;
                } catch (e) {
                    console.log('Click method failed:', e.message);
                }
                await this.delay(200);
            }

            return false;
        }

        isElementInteractable(element) {
            if (!element) return false;
            if (element.disabled) return false;
            return this.isElementVisible(element);
        }

        isElementVisible(element) {
            const style = window.getComputedStyle(element);
            return style.display !== 'none' &&
                   style.visibility !== 'hidden' &&
                   element.offsetWidth > 0 &&
                   element.offsetHeight > 0;
        }

        delay(ms) {
            return new Promise(resolve => setTimeout(resolve, ms));
        }
    }

    // Initialize appropriate handler based on context
    function initializeScript() {
        // Check if we're likely in the second tab (reservation page)
        const isReservationPage = window.location.href.includes('reservation') || 
                                 document.querySelector('form') !== null;

        if (isReservationPage) {
            // Second tab handler
            new SecondTabHandler();
        } else {
            // First tab handler (main page)
            new ReservationController();
        }
    }

    // Start script when page loads
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initializeScript);
    } else {
        initializeScript();
    }

})();

