@app.route('/api/photos/search', methods=['GET'])
def search_photos():
    """
    Search photos with advanced filtering and partial matching
    """
    # Get query parameters
    query = request.args.get('q', '').strip()
    min_price = request.args.get('min_price')
    max_price = request.args.get('max_price')
    sort_by = request.args.get('sort_by', 'price')  # price, name, date
    sort_order = request.args.get('order', 'asc')  # asc, desc
    group_by = request.args.get('group_by')  # name, price_range
    limit = request.args.get('limit', 20, type=int)
    offset = request.args.get('offset', 0, type=int)

    # Base query for active photos only
    query_base = Photo.query.filter_by(is_active=True, status='approved')

    # Apply text search with partial matching
    if query:
        search_terms = query.split()
        for term in search_terms:
            term_pattern = f'%{term}%'
            query_base = query_base.filter(
                (Photo.name.ilike(term_pattern)) |
                (Photo.description.ilike(term_pattern))
            )

    # Apply price range filter
    if min_price:
        try:
            query_base = query_base.filter(Photo.price >= float(min_price))
        except ValueError:
            pass

    if max_price:
        try:
            query_base = query_base.filter(Photo.price <= float(max_price))
        except ValueError:
            pass

    # Apply sorting
    if sort_by == 'price':
        if sort_order == 'asc':
            query_base = query_base.order_by(Photo.price.asc())
        else:
            query_base = query_base.order_by(Photo.price.desc())
    elif sort_by == 'name':
        if sort_order == 'asc':
            query_base = query_base.order_by(Photo.name.asc())
        else:
            query_base = query_base.order_by(Photo.name.desc())
    elif sort_by == 'date':
        if sort_order == 'asc':
            query_base = query_base.order_by(Photo.submitted_at.asc())
        else:
            query_base = query_base.order_by(Photo.submitted_at.desc())

    # Get total count before pagination
    total_count = query_base.count()

    # Apply pagination
    photos = query_base.limit(limit).offset(offset).all()

    # Group results if requested
    results = []
    if group_by == 'name':
        # Already grouped by name (one photo per name)
        results = [{
            'group_key': photo.name,
            'photos': [photo_to_dict(photo)],
            'count': 1
        } for photo in photos]
    elif group_by == 'price_range':
        # Group by price ranges
        price_ranges = [
            (0, 10, '$0-10'),
            (10, 25, '$10-25'),
            (25, 50, '$25-50'),
            (50, 100, '$50-100'),
            (100, 250, '$100-250'),
            (250, 500, '$250-500'),
            (500, float('inf'), '$500+')
        ]

        grouped = {}
        for min_p, max_p, label in price_ranges:
            range_photos = [
                p for p in photos 
                if min_p <= p.price < max_p
            ]
            if range_photos:
                grouped[label] = {
                    'photos': [photo_to_dict(p) for p in range_photos],
                    'count': len(range_photos),
                    'avg_price': sum(p.price for p in range_photos)/len(range_photos)
                }

        results = [{
            'group_key': k,
            **v
        } for k, v in grouped.items()]
    else:
        # No grouping - flat list
        results = [photo_to_dict(photo) for photo in photos]

    return jsonify({
        'results': results,
        'total': total_count,
        'limit': limit,
        'offset': offset,
        'has_more': (offset + len(results)) < total_count,
        'search_params': {
            'query': query,
            'min_price': min_price,
            'max_price': max_price,
            'sort_by': sort_by,
            'sort_order': sort_order,
            'group_by': group_by
        }
    })

def photo_to_dict(photo):
    """Convert Photo object to dictionary"""
    return {
        'id': photo.id,
        'name': photo.name,
        'price': float(photo.price),
        'description': photo.description,
        'filename': photo.filename,
        'image_url': f'/api/photos/image/{photo.filename}',
        'submitted_at': photo.submitted_at.isoformat(),
        'status': photo.status
    }
