class SearchActivity : AppCompatActivity() {
    private lateinit var binding: ActivitySearchBinding
    private lateinit var adapter: PhotoAdapter
    private lateinit var photoApi: PhotoApiService

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivitySearchBinding.inflate(layoutInflater)
        setContentView(binding.root)

        // Setup RecyclerView
        adapter = PhotoAdapter()
        binding.recyclerView.layoutManager = LinearLayoutManager(this)
        binding.recyclerView.adapter = adapter

        // Setup API client
        val retrofit = Retrofit.Builder()
            .baseUrl("http://your-api-url/")
            .addConverterFactory(GsonConverterFactory.create())
            .build()
        photoApi = retrofit.create(PhotoApiService::class.java)

        // Setup search
        setupSearchView()
        setupFilterControls()
    }

    private fun setupSearchView() {
        binding.searchView.setOnQueryTextListener(object : SearchView.OnQueryTextListener {
            override fun onQueryTextSubmit(query: String): Boolean {
                performSearch(query)
                return true
            }

            override fun onQueryTextChange(newText: String): Boolean {
                if (newText.isEmpty()) {
                    performSearch("")
                }
                return true
            }
        })
    }

    private fun setupFilterControls() {
        binding.btnApplyFilters.setOnClickListener {
            val minPrice = binding.etMinPrice.text.toString()
            val maxPrice = binding.etMaxPrice.text.toString()
            val sortBy = when(binding.spSortBy.selectedItemPosition) {
                0 -> "price"
                1 -> "name"
                2 -> "date"
                else -> "price"
            }
            val sortOrder = if (binding.cbSortDesc.isChecked) "desc" else "asc"

            val currentQuery = binding.searchView.query.toString()
            performSearch(currentQuery, minPrice, maxPrice, sortBy, sortOrder)
        }
    }

    private fun performSearch(
        query: String,
        minPrice: String? = null,
        maxPrice: String? = null,
        sortBy: String = "price",
        sortOrder: String = "asc"
    ) {
        CoroutineScope(Dispatchers.IO).launch {
            try {
                val response = photoApi.searchPhotos(
                    q = query,
                    min_price = minPrice,
                    max_price = maxPrice,
                    sort_by = sortBy,
                    order = sortOrder,
                    group_by = if (binding.cbGroupResults.isChecked) "name" else null
                )

                withContext(Dispatchers.Main) {
                    if (response.isSuccessful) {
                        val searchResponse = response.body()
                        searchResponse?.let {
                            adapter.submitList(it.results)
                            updateSearchStats(it.total, it.search_params)
                        }
                    } else {
                        showError("Search failed")
                    }
                }
            } catch (e: Exception) {
                withContext(Dispatchers.Main) {
                    showError("Network error: ${e.message}")
                }
            }
        }
    }

    private fun updateSearchStats(total: Int, params: Map<String, String>) {
        binding.tvResultsCount.text = "$total results found"
        // Update UI with current search parameters
    }

    private fun showError(message: String) {
        Toast.makeText(this, message, Toast.LENGTH_SHORT).show()
    }
}
