def optimized_minor_determinant(matrix: List[List[float]], row: int, col: int) -> float:
    """
    Hybrid minor determinant calculation with optimized algorithms for different matrix sizes.

    Args:
        matrix: Square matrix as 2D list
        row: Row to remove (0-based)
        col: Column to remove (0-based)

    Returns:
        Determinant of the minor matrix

    Raises:
        ValueError: For invalid inputs
    """
    # Input validation
    if not matrix:
        raise ValueError("Matrix cannot be empty")

    n = len(matrix)

    # Check if square
    for i in range(n):
        if len(matrix[i]) != n:
            raise ValueError(f"Matrix must be square. Row {i} has {len(matrix[i])} columns")

    # Check indices
    if row < 0 or row >= n or col < 0 or col >= n:
        raise ValueError(f"Indices out of bounds. Matrix is {n}x{n}")

    # Edge cases
    if n == 1:
        return 1.0  # Convention: determinant of empty matrix is 1

    if n == 2:
        return matrix[1-row][1-col]

    # Create minor matrix efficiently using slicing
    minor_mat = []
    for i in range(n):
        if i == row:
            continue
        minor_mat.append(matrix[i][:col] + matrix[i][col+1:])

    # Choose algorithm based on size
    if n <= 4:
        return optimized_small_matrix_det(minor_mat)
    else:
        return lu_determinant(minor_mat)


def optimized_small_matrix_det(matrix: List[List[float]]) -> float:
    """
    Highly optimized determinant for small matrices (n ≤ 4).
    Uses direct formulas for n=1-3 and optimized Laplace expansion for n=4.
    """
    n = len(matrix)

    if n == 1:
        return matrix[0][0]

    if n == 2:
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]

    if n == 3:
        # Sarrus' rule
        a, b, c = matrix[0]
        d, e, f = matrix[1]
        g, h, i = matrix[2]
        return (a*e*i + b*f*g + c*d*h) - (c*e*g + b*d*i + a*f*h)

    if n == 4:
        # Optimized 4x4 using Laplace expansion
        # Precompute all 2x2 determinants needed for the 3x3 minors
        # This reduces the number of operations compared to naive recursion
        a, b, c, d = matrix[0]
        e, f, g, h = matrix[1]
        i, j, k, l = matrix[2]
        m, n, o, p = matrix[3]

        # Compute all necessary 2x2 determinants
        det1 = f*(k*p - l*o) - g*(j*p - l*n) + h*(j*o - k*n)
        det2 = e*(k*p - l*o) - g*(i*p - l*m) + h*(i*o - k*m)
        det3 = e*(j*p - l*n) - f*(i*p - l*m) + h*(i*n - j*m)
        det4 = e*(j*o - k*n) - f*(i*o - k*m) + g*(i*n - j*m)

        return a*det1 - b*det2 + c*det3 - d*det4

    # Fallback for n > 4 (shouldn't be called in this function)
    return lu_determinant(matrix)


def lu_determinant(matrix: List[List[float]]) -> float:
    """
    Compute determinant using LU decomposition with partial pivoting.
    Time Complexity: O(n³)
    Space Complexity: O(n²)
    """
    n = len(matrix)

    # Convert to numpy array for efficient LU decomposition
    A = np.array(matrix, dtype=float)

    # Perform LU decomposition with partial pivoting
    try:
        # Get the sign from the permutation matrix
        _, pivots = np.linalg.lu_factor(A)
        sign = 1

        # Count the number of row swaps
        for i in range(n):
            if pivots[i] != i:
                sign *= -1

        # Determinant is product of diagonal of U multiplied by sign
        return sign * np.prod(np.diag(np.linalg.lu(A)[2]))
    except np.linalg.LinAlgError:
        # Matrix is singular
        return 0.0


