            const auto& src_row = data[i];
            auto& dst_row = minor_buffer[minor_i];

            // Use STL copy_if with lambda for column filtering
            auto it = std::copy_if(src_row.begin(), src_row.end(), dst_row.begin(),
                [col, j=0](const T&) mutable { return j++ != col; });

            ++minor_i;
        }
    }

    T optimizedSmallMatrixDet(const std::vector<std::vector<T>>& mat) const {
        const size_t m = mat.size();

        switch (m) {
            case 1: return mat[0][0];

            case 2: // Optimized 2x2
                return mat[0][0] * mat[1][1] - mat[0][1] * mat[1][0];

            case 3: { // Sarrus' rule for 3x3
                const auto& a = mat[0], &b = mat[1], &c = mat[2];
                return a[0]*(b[1]*c[2] - b[2]*c[1])
                     - a[1]*(b[0]*c[2] - b[2]*c[0])
