            case 4: { // Optimized 4x4 using Laplace expansion
                const auto& a = mat[0], &b = mat[1], &c = mat[2], &d = mat[3];

                // Precompute all 2x2 determinants needed for the 3x3 minors
                auto det2x2 = [](T a, T b, T c, T d) { return a*d - b*c; };

                T det1 = b[1]*det2x2(c[2],c[3],d[2],d[3]) 
                       - b[2]*det2x2(c[1],c[3],d[1],d[3]) 
                       + b[3]*det2x2(c[1],c[2],d[1],d[2]);

                T det2 = b[0]*det2x2(c[2],c[3],d[2],d[3]) 
                       - b[2]*det2x2(c[0],c[3],d[0],d[3]) 
                       + b[3]*det2x2(c[0],c[2],d[0],d[2]);

                T det3 = b[0]*det2x2(c[1],c[3],d[1],d[3]) 
