                       - b[1]*det2x2(c[0],c[2],d[0],d[2]) 
                       + b[2]*det2x2(c[0],c[1],d[0],d[1]);

                return a[0]*det1 - a[1]*det2 + a[2]*det3 - a[3]*det4;
