## Part 4: Error Handling and Common Pitfalls

When building a query parser, robust error handling is crucial. Let's enhance our parser with comprehensive error checking and discuss common pitfalls.

### Step 1: Enhanced Error Handling

First, let's create custom exception classes for better error reporting:

```python
class QueryParserError(Exception):
    """Base exception for query parser errors"""
    pass

class SyntaxError(QueryParserError):
    """Raised when SQL syntax is invalid"""
    pass

class SemanticError(QueryParserError):
    """Raised when SQL semantics are invalid"""
    pass

class UnsupportedFeatureError(QueryParserError):
    """Raised when encountering unsupported SQL features"""
    pass
```

### Step 2: Enhanced Query Parser with Error Handling

```python
class RobustQueryParser(EnhancedQueryParser):
    """Query parser with comprehensive error handling"""

    def __init__(self):
        self._validated_tables = set()
        self._validated_columns = {}

    def parse(self, sql_ast: SQL_AST) -> RA_Node:
        """Main entry point with error handling"""
        try:
            # Validate the SQL AST structure
            self._validate_sql_ast(sql_ast)

            # Parse based on AST type
            if isinstance(sql_ast, SelectStatement):
                return self._parse_select(sql_ast)
            elif isinstance(sql_ast, SelectWithJoin):
                return self._parse_select_with_join(sql_ast)
            else:
                raise UnsupportedFeatureError(
                    f"Unsupported SQL AST type: {type(sql_ast).__name__}"
                )

        except QueryParserError:
            # Re-raise our custom exceptions
            raise
        except Exception as e:
            # Catch any unexpected errors
            raise QueryParserError(f"Unexpected error during parsing: {str(e)}")

    def _validate_sql_ast(self, sql_ast: SQL_AST) -> None:
        """Validate the structure of SQL AST"""
        if sql_ast is None:
            raise SyntaxError("SQL AST cannot be None")

        if isinstance(sql_ast, SelectStatement):
            self._validate_select_statement(sql_ast)
        elif isinstance(sql_ast, SelectWithJoin):
            self._validate_select_with_join(sql_ast)

    def _validate_select_statement(self, select_stmt: SelectStatement) -> None:
        """Validate basic SELECT statement"""
        # Check table name
        if not select_stmt.table or not isinstance(select_stmt.table, str):
            raise SyntaxError(f"Invalid table name: {select_stmt.table}")

        # Check columns
        if not select_stmt.columns:
            raise SyntaxError("SELECT statement must have at least one column")

        for column in select_stmt.columns:
            if not column or not isinstance(column, str):
                raise SyntaxError(f"Invalid column name: {column}")

        # Check WHERE clause if present
        if select_stmt.where_clause:
            self._validate_condition(select_stmt.where_clause)

    def _validate_select_with_join(self, select_stmt: SelectWithJoin) -> None:
        """Validate SELECT statement with JOINs"""
        # Check columns
        if not select_stmt.columns:
            raise SyntaxError("SELECT statement must have at least one column")

        for column in select_stmt.columns:
            if not column or not isinstance(column, str):
                raise SyntaxError(f"Invalid column name: {column}")

        # Check JOINs
        if not select_stmt.joins:
            raise SyntaxError("SelectWithJoin must have at least one JOIN")

        for join_clause in select_stmt.joins:
            self._validate_join_clause(join_clause)

        # Check WHERE clause if present
        if select_stmt.where_clause:
            self._validate_condition(select_stmt.where_clause)

    def _validate_join_clause(self, join_clause: JoinClause) -> None:
        """Validate JOIN clause"""
        # Check join type
        valid_join_types = {"INNER", "LEFT", "RIGHT", "FULL"}
        if join_clause.join_type not in valid_join_types:
            raise SyntaxError(
                f"Invalid join type: {join_clause.join_type}. "
                f"Valid types are: {', '.join(valid_join_types)}"
            )

        # Check table names
        if not join_clause.left_table or not isinstance(join_clause.left_table, str):
            raise SyntaxError(f"Invalid left table name: {join_clause.left_table}")

        if not join_clause.right_table or not isinstance(join_clause.right_table, str):
            raise SyntaxError(f"Invalid right table name: {join_clause.right_table}")

        # Check condition if present
        if join_clause.condition:
            self._validate_condition(join_clause.condition)

    def _validate_condition(self, condition: Any) -> None:
        """Validate condition structure"""
        if condition is None:
            return

        if isinstance(condition, Condition):
            # Check basic condition
            if not condition.column or not isinstance(condition.column, str):
                raise SyntaxError(f"Invalid column in condition: {condition.column}")

            if not condition.operator or not isinstance(condition.operator, str):
                raise SyntaxError(f"Invalid operator: {condition.operator}")

            # Check for valid operators
            valid_operators = {"=", "!=", "<>", "<", ">", "<=", ">=", "LIKE", "IN"}
            if condition.operator.upper() not in valid_operators:
                raise SyntaxError(
                    f"Invalid operator: {condition.operator}. "
                    f"Valid operators are: {', '.join(valid_operators)}"
                )

        elif isinstance(condition, (AndCondition, OrCondition)):
            # Recursively validate complex conditions
            self._validate_condition(condition.left)
            self._validate_condition(condition.right)

        else:
            raise SyntaxError(f"Invalid condition type: {type(condition).__name__}")

    def _parse_select(self, select_stmt: SelectStatement) -> RA_Node:
        """Parse SELECT statement with validation"""
        # Additional semantic validation
        if select_stmt.columns == ["*"]:
            # In a real implementation, you would need to fetch actual column names
            pass

        return super()._parse_select(select_stmt)

    def _parse_select_with_join(self, select_stmt: SelectWithJoin) -> RA_Node:
        """Parse SELECT statement with JOINs with validation"""
        # Check for ambiguous column names
        self._check_column_ambiguity(select_stmt)

        return super()._parse_select_with_join(select_stmt)

    def _check_column_ambiguity(self, select_stmt: SelectWithJoin) -> None:
        """Check for ambiguous column references in JOIN queries"""
        column_sources = {}

        for column in select_stmt.columns:
            if '.' in column:
                # Column is qualified with table name
                table_name, col_name = column.split('.', 1)
                if col_name in column_sources and column_sources[col_name] != table_name:
                    raise SemanticError(
                        f"Ambiguous column reference: {col_name} "
                        f"(could be from {column_sources[col_name]} or {table_name})"
                    )
                column_sources[col_name] = table_name
            else:
                # Unqualified column - check if it appears in multiple tables
                pass  # In a real implementation, you'd track table schemas
